using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] entries) =>
        entries.Select(e => new OrderItem { ProductName = e.name, Price = e.price, Quantity = e.qty }).ToList();

    #region CreateOrder – happy path

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2), ("Gadget", 25m, 1));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(45m, order.Total); // 10*2 + 25*1
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_SetsTotalToItemTotal()
    {
        var items = CreateItems(("Book", 15.50m, 3));

        var order = _service.CreateOrder("cust-2", items);

        Assert.AreEqual(46.50m, order.Total); // 15.50 * 3
        Assert.ContainsSingle(order.Items);
    }

    [TestMethod]
    public void CreateOrder_AssignsUniqueId()
    {
        var items = CreateItems(("Item", 5m, 1));

        var order1 = _service.CreateOrder("cust-1", items);
        var order2 = _service.CreateOrder("cust-1", items);

        Assert.IsNotNull(order1.Id);
        Assert.IsNotNull(order2.Id);
        Assert.AreNotEqual(order1.Id, order2.Id);
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentUtcTime()
    {
        var before = DateTime.UtcNow;
        var items = CreateItems(("Clock", 30m, 1));

        var order = _service.CreateOrder("cust-1", items);

        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= DateTime.UtcNow);
    }

    #endregion

    #region CreateOrder – validation / exceptions

    [TestMethod]
    public void CreateOrder_NullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems(("Item", 1m, 1));

        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_NullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_EmptyItems_ThrowsInvalidOperationException()
    {
        Assert.ThrowsExactly<InvalidOperationException>(() => _service.CreateOrder("cust-1", []));
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_ExistingOrder_ReturnsSameInstance()
    {
        var items = CreateItems(("Pen", 2m, 5));
        var created = _service.CreateOrder("cust-1", items);

        var retrieved = _service.GetOrder(created.Id);

        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_NonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_MultipleOrders_ReturnsAll()
    {
        var items = CreateItems(("Item", 1m, 1));
        _service.CreateOrder("cust-A", items);
        _service.CreateOrder("cust-A", items);
        _service.CreateOrder("cust-B", items);

        var results = _service.GetOrdersByCustomer("cust-A");

        Assert.HasCount(2, results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_NoOrders_ReturnsEmptyList()
    {
        var results = _service.GetOrdersByCustomer("no-orders");

        Assert.IsEmpty(results);
    }

    [TestMethod]
    public void GetOrdersByCustomer_DoesNotReturnOtherCustomerOrders()
    {
        var items = CreateItems(("Item", 1m, 1));
        var other = _service.CreateOrder("cust-X", items);

        var results = _service.GetOrdersByCustomer("cust-Y");

        Assert.DoesNotContain(other, results);
    }

    #endregion

    #region Data-driven: total calculation

    [TestMethod]
    [DynamicData(nameof(TotalTestData))]
    public void CreateOrder_CalculatesCorrectTotal(string label, decimal price, int qty, decimal expected)
    {
        var items = CreateItems((label, price, qty));

        var order = _service.CreateOrder("cust-1", items);

        Assert.AreEqual(expected, order.Total);
    }

    public static IEnumerable<(string label, decimal price, int qty, decimal expected)> TotalTestData =>
    [
        ("Zero-price item", 0m, 5, 0m),
        ("Zero-quantity item", 10m, 0, 0m),
        ("Standard item", 19.99m, 3, 59.97m),
    ];

    #endregion
}

